begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001201','open.summary@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values('00000000-0000-4000-8000-000000001201','00000000-0000-4000-8000-000000001201','open.summary@example.test','Equipo');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000001201','designer'),('00000000-0000-4000-8000-000000001201','operator'),('00000000-0000-4000-8000-000000001201','finance');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000001201';
select public.save_customer('00000000-0000-4000-8000-000000001221',null,'{"display_name":"Cliente resumen"}');
select public.create_direct_order('00000000-0000-4000-8000-000000001222','00000000-0000-4000-8000-000000001221',null,null,'','[{"description":"Trabajo 1222","quantity":1,"amount":"200"}]','{"amount":"50","paid_on":"1901-01-15","method":"cash"}');
select public.complete_production('00000000-0000-4000-8000-000000001222',null,'Listo');
select public.create_direct_order('00000000-0000-4000-8000-000000001223','00000000-0000-4000-8000-000000001221',null,null,'','[{"description":"Trabajo 1223","quantity":1,"amount":"300"}]','{"amount":"300","paid_on":"1901-01-15","method":"cash"}');
select public.complete_production('00000000-0000-4000-8000-000000001223',null,'Listo');
select public.create_direct_order('00000000-0000-4000-8000-000000001224','00000000-0000-4000-8000-000000001221',null,null,'','[{"description":"Trabajo 1224","quantity":1,"amount":"100"}]',null);
select public.complete_production('00000000-0000-4000-8000-000000001224',null,'Listo');
select public.create_direct_order('00000000-0000-4000-8000-000000001225','00000000-0000-4000-8000-000000001221',null,null,'','[{"description":"Trabajo 1225","quantity":1,"amount":"400"}]','{"amount":"20","paid_on":"1901-01-15","method":"cash"}');
select public.record_payment('00000000-0000-4000-8000-000000001250','00000000-0000-4000-8000-000000001222',50,'1901-01-15','cash','Cobro');
select is(jsonb_array_length(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'),2,'Solo terminados con saldo');
select is(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'->0->>'id','00000000-0000-4000-8000-000000001222','La nota más vieja aparece primero');
select is(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'->1->>'id','00000000-0000-4000-8000-000000001224','Orden ascendente por número');
select ok(position('00000000-0000-4000-8000-000000001223' in public.customer_completed_summary('00000000-0000-4000-8000-000000001221')::text)=0,'Excluye nota totalmente cubierta por seña');
select ok(position('00000000-0000-4000-8000-000000001225' in public.customer_completed_summary('00000000-0000-4000-8000-000000001221')::text)=0,'Excluye trabajos sin terminar aunque tengan saldo');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->>'balance')::numeric,200::numeric,'Suma solo saldo de notas incluidas');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'->0->>'paid')::numeric,100::numeric,'Descuenta seña y otros pagos');
select is((public.customer_work_summary('00000000-0000-4000-8000-000000001221')->'orders'->0->>'number')::bigint,(select number from public.orders where id='00000000-0000-4000-8000-000000001222'),'Resumen interno también orden ascendente');
select public.record_payment('00000000-0000-4000-8000-000000001251','00000000-0000-4000-8000-000000001222',100,'1901-01-15','cash','Saldo');
select is(jsonb_array_length(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'),1,'Al completar pago la nota desaparece');
select is(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'->0->>'id','00000000-0000-4000-8000-000000001224','Conserva otra nota pendiente');
select is((select count(*) from public.orders where id='00000000-0000-4000-8000-000000001222'),1::bigint,'Nota pagada permanece en historial');
select public.record_payment('00000000-0000-4000-8000-000000001252','00000000-0000-4000-8000-000000001224',100,'1901-01-15','cash','Saldo');
select is(jsonb_array_length(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'),0,'Resumen vacío si todos los terminados están pagados');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->>'balance')::numeric,0::numeric,'Resumen saldado sin deuda');
-- Dato legado con sobrepago: el resumen lo conserva como saldo a favor.
reset role;
update public.money_movements set amount=320 where order_id='00000000-0000-4000-8000-000000001223' and kind='deposit';
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000001201';
select is(jsonb_array_length(public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->'orders'),1,'Conserva saldo a favor si existe');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001221')->>'balance')::numeric,-20::numeric,'Saldo a favor no se presenta como deuda');
reset role;
select * from finish();
rollback;
